column7:
결과:[
  {
    "issue": "기후변화 대응",
    "sub_issue": "제조공정, 공급망, 제품 포트폴리오 및 제품 사용 등 가치사슬 전반에 걸친 온실가스 감축 및 친환경 차량 부품 전환을 통한 글로벌 규제 대응"
  },
  {
    "issue": "공급망 지속가능성 관리",
    "sub_issue": "원자재 채굴 및 가공 과정의 환경·노동권 리스크 관리, 협력사 ESG 진단 및 공급망 안정성 확보"
  },
  {
    "issue": "제품 품질 및 안전 확보",
    "sub_issue": "제품 품질 향상 및 안전성 확보를 통한 고객 신뢰 구축 및 재무적 리스크 최소화"
  },
  {
    "issue": "자원 사용 및 순환 경제",
    "sub_issue": "자원 재활용, 부품 소재 경량화 및 친환경 제품 생산을 통한 환경 오염 저감과 순환 체계 구축"
  },
  {
    "issue": "인적자원 관리",
    "sub_issue": "모빌리티 기술 변화에 대응하는 전문 인력 육성, 우수 인재 확보 및 공정한 채용을 통한 사회적 가치 창출"
  },
  {
    "issue": "신뢰받는 노사관계",
    "sub_issue": "노사 간 신뢰 구축 및 협력적 관계 유지를 통한 안정적인 경영 환경 조성"
  },
  {
    "issue": "산업 안전보건 강화",
    "sub_issue": "사업장 내 안전보건 관리 체계 강화 및 재해 예방을 통한 임직원 안전 확보"
  },
  {
    "issue": "정보보안 강화",
    "sub_issue": "사이버 보안 위협 대응 및 고객·기업 정보 보호 체계 고도화"
  },
  {
    "issue": "기업지배구조",
    "sub_issue": "투명하고 건전한 지배구조 확립 및 이사회 중심의 책임 경영 실천"
  },
  {
    "issue": "컴플라이언스 경영",
    "sub_issue": "법규 준수 및 윤리경영 강화를 통한 준법 리스크 예방 및 투명성 제고"
  },
  {
    "issue": "다양성 및 포용성",
    "sub_issue": "다양성을 존중하는 조직 문화 조성 및 차별 없는 공정한 기회 제공"
  }
]

